begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(2307032061141443598)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_name=>'Retrieve the saved theme preference after login'
,p_static_id=>'retrieve-the-saved-theme-preference-after-login'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- DECLARE',
'--     -- Stores the previously saved theme preference',
'--     v_theme_preference VARCHAR2(100);',
'',
'-- BEGIN',
'--     /*',
'--       Retrieve the theme preference saved for the',
'--       currently authenticated APEX user.',
'--     */',
'--     v_theme_preference := apex_util.get_preference(',
'--         p_preference => ''APP_THEME_PREFERENCE''',
'--     );',
'',
'--     /*',
'--       Synchronize the Switch item with the saved preference.',
'--     */',
'--     IF v_theme_preference = ''DARK'' THEN',
'--         :P0_THEME_SWITCH := ''Y'';',
'--     ELSE',
'--         -- Use Light theme when no preference exists',
'--         :P0_THEME_SWITCH := ''N'';',
'--     END IF;',
'',
'-- END;',
'',
'',
'',
'NULL;'))
,p_process_clob_language=>'PLSQL'
,p_process_when_type=>'NEVER'
,p_version_scn=>'SH256:hqH5ldmAoaCsNo_7f2M1n4rJ9rJxq5kEH0FSUzN6Fkw'
,p_created_on=>wwv_flow_imp.dz('20261012055154Z')
,p_updated_on=>wwv_flow_imp.dz('20261016071559Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
