prompt --application/shared_components/user_interface/templates/report/report_cards_cotton_reverse
begin
wwv_flow_imp_shared.create_row_template(
 p_id=>wwv_flow_imp.id(4693481076353107733)
,p_row_template_name=>'REPORT_CARDS_COTTON_REVERSE'
,p_static_id=>'report-cards-cotton-reverse'
,p_row_template1=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<li class="t-Cards-item #CARD_MODIFIERS#">',
'    <div class="t-Card">',
'        <a href="#CARD_LINK#" class="t-Card-wrap">',
'            <div class="t-Card-icon u-color #CARD_COLOR#">',
'                <span class="t-Icon fa #CARD_ICON#"><span class="t-Card-initials" role="presentation">#CARD_INITIALS#</span></span>',
'            </div>',
'            <div class="t-Card-body">',
'                <div class="reverse-cost-card">',
'                    <div class="reverse-card-title">',
'                        Buying Parity (Max Purchase Rate)',
'                    </div>',
'                    <div class="reverse-price-section">',
unistr('                        <span class="reverse-price">\20B9 #VALUE#</span>'),
'                        <span class="reverse-unit">/ 20kg Raw Cotton</span>',
'                    </div>',
'                    <div class="reverse-card-divider"></div>',
'                    <div class="reverse-card-description">',
'                        <span class="reverse-check-icon">&#10003;</span>',
'                        <span>You can pay up to this amount for Raw Cotton to break even.</span>',
'                    </div>',
'                </div>',
'            </div>',
'            <span class="t-Card-colorFill u-color #CARD_COLOR#"></span>',
'        </a>',
'    </div>',
'</li>'))
