,p_plug_template=>4075786578761660127
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<!-- <div id="loadingOverlay" class="loading-overlay">',
'    <div class="loading-content">',
'       <img src="#APP_FILES#penguin.gif" alt="Loading" class="loading-icon">',
'    </div>',
'</div>',
'',
'<style>',
' .loading-overlay {',
'    position: fixed;',
'    top: 0;',
'    left: 0;',
'    width: 100%;',
'    height: 100%;',
'    background-color: rgba(255, 255, 255, 0.7);',
'    display: flex;',
'    justify-content: center;',
'    align-items: center;',
'    z-index: 9999;',
'    display: none;',
'  }',
'',
'  .loading-icon {',
'    width: 250px;',
'    animation: fadeIn 2s infinite;',
'   }',
'',
'  @keyframes fadeIn {',
'    0% { opacity: 0; }',
'    50% { opacity: 1; }',
'    100% { opacity: 0; }',
'   }',
'</style> -->',
'',
'',
'',
'',
'',
'',
'',
'',
'<div id="loadingOverlay" class="loading-overlay">',
'    <div class="loader-wrapper">',
'',
'        <div class="loader-circle">',
'            <div class="loader-spinner"></div>',
'',
'            <div class="loader-icon">',
'                <svg viewBox="0 0 64 64" aria-hidden="true">',
'                    <path d="M32 37',
'                             C19 37 12 28 16 19',
'                             C20 12 29 16 32 25',
'                             C35 16 44 12 48 19',
'                             C52 28 45 37 32 37Z"',
'                          fill="#FFFFFF"',
'                          stroke="#4655F5"',
'                          stroke-width="2.5"/>',
'',
'                    <path d="M32 35',
'                             C24 30 23 20 32 10',
'                             C41 20 40 30 32 35Z"',
'                          fill="#4655F5"/>',
'',
'                    <path d="M31 34',
'                             C24 28 17 29 12 32',
'                             C17 39 24 41 31 37Z"',
'                          fill="#4655F5"/>',
'',
'                    <path d="M33 34',
'                             C40 28 47 29 52 32',
'                             C47 39 40 41 33 37Z"',
'                          fill="#4655F5"/>',
'',
'                    <path d="M32 34 L32 48"',
'                          stroke="#4655F5"',
'                          stroke-width="3.5"',
'                          stroke-linecap="round"/>',
'                </svg>',
'            </div>',
'        </div>',
'',
'        <div class="loader-title">Cotton Calculator Pro</div>',
'        <div class="loader-subtitle">Loading...</div>',
'',
'        <div class="loader-progress">',
'            <div class="loader-progress-bar"></div>',
'        </div>',
'',
'    </div>',
'</div>',
'',
'',
'',
'',
'<style>',
'.loading-overlay {',
'    position: fixed;',
'    inset: 0;',
'    z-index: 99999;',
'    display: flex;',
'    justify-content: center;',
'    align-items: center;',
'    background: #e8edf5;',
'    transition: opacity 0.3s ease;',
'    display: none;',
'}',
'',
'.loader-wrapper {',
'    display: flex;',
'    flex-direction: column;',
'    align-items: center;',
'    gap: 8px;',
'    padding: 15px;',
'    text-align: center;',
'}',
'',
'/* Compact neumorphic circle */',
'.loader-circle {',
'    position: relative;',
'    width: 90px;',
'    height: 90px;',
'    display: flex;',
'    align-items: center;',
'    justify-content: center;',
'    border-radius: 50%;',
'    background: #e8edf5;',
'    box-shadow: 8px 8px 18px #cbd2df, -8px -8px 18px #ffffff;',
'}',
'',
'/* Rotating spinner */',
'.loader-spinner {',
'    position: absolute;',
'    inset: 7px;',
'    border-radius: 50%;',
'    border: 4px solid #d5dcff;',
'    border-top-color: #4655f5;',
'    border-right-color: #4655f5;',
'    animation: loaderRotate 1s linear infinite;',
'}',
'',
'/* Cotton icon container */',
'.loader-icon {',
'    width: 42px;',
'    height: 42px;',
'    display: flex;',
'    align-items: center;',
'    justify-content: center;',
'    border-radius: 14px;',
'    background: #e8edf5;',
'    box-shadow: 4px 4px 9px #cbd2df, -4px -4px 9px #ffffff;',
'}',
'',
'.loader-icon svg {',
'    width: 32px;',
'    height: 32px;',
'}',
'',
'/* Application title */',
'.loader-title {',
'    margin-top: 6px;',
'    color: #4050ef;',
'    font-size: 18px;',
'    font-weight: 800;',
'    letter-spacing: -0.4px;',
'}',
'',
'/* Loading text */',
'.loader-subtitle {',
'    color: #71809b;',
'    font-size: 12px;',
'    font-weight: 500;',
'    animation: loaderPulse 1.5s ease-in-out infinite;',
'}',
'',
'/* Progress bar */',
'.loader-progress {',
'    width: 130px;',
'    height: 4px;',
'    margin-top: 4px;',
'    overflow: hidden;',
'    border-radius: 20px;',
'    background: #d9e0ed;',
'    box-shadow: inset 2px 2px 5px #cbd2df, inset -2px -2px 5px #ffffff;',
'}',
'',
'.loader-progress-bar {',
'    width: 40%;',
'    height: 100%;',
'    border-radius: 20px;',
'    background: linear-gradient(',
'        90deg,',
'        #6875ff,',
'        #3949ef',
'    );',
'    animation: loaderProgress 1.4s ease-in-out infinite;',
'}',
'',
'/* Animations */',
'@keyframes loaderRotate {',
'    to {',
'        transform: rotate(360deg);',
'    }',
'}',
'',
'@keyframes loaderPulse {',
'    0%, 100% {',
'        opacity: 0.55;',
'    }',
'',
'    50% {',
'        opacity: 1;',
'    }',
'}',
'',
'@keyframes loaderProgress {',
'    0% {',
'        transform: translateX(-110%);',
'    }',
'',
'    100% {',
'        transform: translateX(350%);',
'    }',
'}',
'</style>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
