 p_id=>wwv_flow_imp.id(45569502504518393611)
,p_event_id=>wwv_flow_imp.id(45569502447963393610)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_static_id=>'native-execute-plsql-code'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_submit', 'P0_THEME_SWITCH',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    '    -- Stores the ID of the selected theme style',
    '    v_theme_style_id NUMBER;',
    '',
    '    -- Stores the theme number of the current application',
    '    v_theme_number NUMBER;',
    '',
    '    -- Stores the Static ID of the theme style to apply',
    '    v_theme_static_id VARCHAR2(100);',
    '',
    '    -- Stores the selected theme preference',
    '    v_theme_preference VARCHAR2(100);',
    '',
    'BEGIN',
    '    /*',
    '   -- Get Application Theme Static Id',
    '    SELECT STATIC_ID,THEME_STYLE_ID FROM apex_application_theme_styles ',
    '    WHERE APPLICATION_ID = :APP_ID',
    '    */',
    '',
    '    /*',
    '      Step 1: Determine the selected theme.',
    '      Y = Dark theme',
    '      N = Light theme',
    '    */',
    '    IF :P0_THEME_SWITCH = ''Y'' THEN',
    '        v_theme_static_id := ''vita-dark'';',
    '        v_theme_preference := ''DARK'';',
    '    ELSE',
    '        v_theme_static_id := ''redwood-light'';',
    '        v_theme_preference := ''LIGHT'';',
    '    END IF;',
    '',
    '    /*',
    '      Step 2: Find the theme style ID and theme number',
    '      for the selected theme in the current application.',
    '    */',
    '    BEGIN',
    '        SELECT',
    '            s.theme_style_id,',
    '            s.theme_number',
    '        INTO',
    '            v_theme_style_id,',
    '            v_theme_number',
    '        FROM apex_application_theme_styles s',
    '        WHERE s.application_id = :APP_ID',
    '          AND s.static_id = v_theme_static_id;',
    '',
    '    EXCEPTION',
    '        WHEN NO_DATA_FOUND THEN',
    '            -- Stop if the selected theme style does not exist',
    '            RAISE_APPLICATION_ERROR(',
    '                -20001,',
    '                ''Selected theme style was not found: ''',
    '                || v_theme_static_id',
    '            );',
    '    END;',
    '',
    '    /*',
    '      Step 3: Apply the selected theme style for the current user.',
    '    */',
    '    apex_theme.set_user_style(',
    '        p_application_id => :APP_ID,',
    '        p_user           => :APP_USER,',
    '        p_theme_number   => v_theme_number,',
    '        p_id             => v_theme_style_id',
    '    );',
    '',
    '    /*',
    '      Step 4: Save the selected theme as a user-specific preference.',
    '      Each authenticated user has their own preference value.',
    '    */',
    '    apex_util.set_preference(',
    '        p_preference => ''APP_THEME_PREFERENCE'',',
    '        p_value      => v_theme_preference',
    '    );',
    '',
    'END;',
    '')),
  'show_processing', 'N')).to_clob
,p_wait_for_result=>'Y'
,p_server_condition_type=>'NEVER'
,p_created_on=>wwv_flow_imp.dz('20261012052746Z')
,p_updated_on=>wwv_flow_imp.dz('20261015102804Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
