,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- SELECT',
'--     ''Cotton Ginning'' AS CARD_TITLE,',
'--     ''Output & Cost Parity: Parity, Reverse & Output'' AS CARD_SUBTITLE,',
'--     ''fa fa-balance-scale'' AS CARD_ICON,',
'--     ''f?p=&APP_ID.:2:&SESSION.'' AS CARD_LINK',
'-- FROM DUAL',
'',
'SELECT',
'    ''Cotton Ginning'' AS CARD_TITLE,',
'    ''Output & Cost Parity: Parity, Reverse & Output'' AS CARD_SUBTITLE,',
'    ''fa fa-balance-scale fa-4x'' AS CARD_ICON,',
'',
'    APEX_PAGE.GET_URL(',
'        p_page => 2',
'    ) AS CARD_LINK,',
'',
'    APEX_PAGE.GET_URL(',
'        p_page        => 2,',
'        p_clear_cache => ''2'',',
'        p_items       => ''P2_ACTIVE_TAB'',',
'        p_values      => ''Parity''',
'    ) AS PARITY_LINK,',
'',
'    APEX_PAGE.GET_URL(',
'        p_page        => 2,',
