'var activeTab = $v("P2_ACTIVE_TAB");',
'',
'if (activeTab === "Parity") {',
'    // Activate the Parity tab',
'} else if (activeTab === "Reverse") {',
'    // Activate the Reverse tab',
'} else if (activeTab === "Output") {',
'    // Activate the Output tab',
'}',
'',
'',
'// redirect to particular tab   ',
'',
'(function () {',
'    var activeTab = ($v("P2_ACTIVE_TAB") || "")',
'        .trim()',
'        .toLowerCase();',
'',
'    var validTabs = ["parity", "reverse", "output"];',
'',
'    if (!validTabs.includes(activeTab)) {',
'        console.warn("Invalid P2_ACTIVE_TAB:", activeTab);',
'        return;',
'    }',
'',
'    function activateTab() {',
'        var tabs = Array.from(',
'            document.querySelectorAll(''[role="tab"]'')',
'        );',
'',
'        console.log(',
'            "Available tabs:",',
'            tabs.map(function (tab) {',
'                return tab.textContent.trim();',
'            })',
'        );',
'',
'        var target = tabs.find(function (tab) {',
'            return tab.textContent.trim().toLowerCase() === activeTab;',
'        });',
'',
'        if (!target) {',
'            console.error("Tab not found by label:", activeTab);',
'            return;',
'        }',
'',
'        target.click();',
'',
'        console.log("Clicked tab:", target.textContent.trim());',
'    }',
'',
'    // Wait for the APEX Tabs Container to initialize.',
'    window.setTimeout(activateTab, 500);',
'})();'))
