,p_chart_id=>wwv_flow_imp.id(1547635626696017644)
,p_static_id=>'ginning-chart'
,p_seq=>10
,p_name=>'Ginning Chart'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- SELECT ''Lint'' AS LABEL,',
'--        NVL(TO_NUMBER(:P2_O_LINT_OUTPUT), 0) AS VALUE',
'-- FROM DUAL',
'',
'-- UNION ALL',
'',
'-- SELECT ''Seed'' AS LABEL,',
'--        NVL(TO_NUMBER(:P2_O_SEED_OUTPUT), 0) AS VALUE',
'-- FROM DUAL',
'',
'-- UNION ALL',
'',
'-- SELECT ''Waste'' AS LABEL,',
'--        NVL(TO_NUMBER(:P2_O_WASTE_LOSS), 0) AS VALUE',
'-- FROM DUAL',
'SELECT',
'    ''Lint'' AS LABEL,',
'    TO_NUMBER(',
'        PKG_GINNING_CALCULATOR.F_CALCULATE_OUTPUT_RATIO(',
'            :P2_O_TOTAL_RAW_COTTON,',
'            :P2_O_LINT_OUTPUT,',
'            :P2_O_SEED_OUTPUT,',
'            :P2_O_WASTE_LOSS,',
'            ''G'',',
'            ''LINT''',
'        )',
'    ) AS VALUE',
'FROM DUAL',
'',
'UNION ALL',
'',
'SELECT',
'    ''Seed'' AS LABEL,',
'    TO_NUMBER(',
'        PKG_GINNING_CALCULATOR.F_CALCULATE_OUTPUT_RATIO(',
'            :P2_O_TOTAL_RAW_COTTON,',
'            :P2_O_LINT_OUTPUT,',
'            :P2_O_SEED_OUTPUT,',
'            :P2_O_WASTE_LOSS,',
'            ''G'',',
'            ''SEED''',
'        )',
'    ) AS VALUE',
'FROM DUAL',
'',
'UNION ALL',
'',
'SELECT',
'    ''Waste'' AS LABEL,',
'    TO_NUMBER(',
