'-- PKG_OIL_MILL_CALCULATOR.CALCULATE_OIL_RECOVERY(:P3_R_TOTAL_SEED_PROCESSED, :P3_R_OIL_REC, :P3_R_CAKE_KHAL, ''OIL_PCT'') || ''%''  AS "Wash Oil",',
'',
'-- PKG_OIL_MILL_CALCULATOR.CALCULATE_OIL_RECOVERY(:P3_R_TOTAL_SEED_PROCESSED, :P3_R_OIL_REC, :P3_R_CAKE_KHAL, ''CAKE_KG'') || ''kg / '' || ',
'-- PKG_OIL_MILL_CALCULATOR.CALCULATE_OIL_RECOVERY(:P3_R_TOTAL_SEED_PROCESSED, :P3_R_OIL_REC, :P3_R_CAKE_KHAL, ''CAKE_PCT'') || ''%''  AS "Oil Cake (Khal)",',
'',
'-- PKG_OIL_MILL_CALCULATOR.CALCULATE_OIL_RECOVERY(:P3_R_TOTAL_SEED_PROCESSED, :P3_R_OIL_REC, :P3_R_CAKE_KHAL, ''WASTE_KG'') || ''kg / '' || ',
'-- PKG_OIL_MILL_CALCULATOR.CALCULATE_OIL_RECOVERY(:P3_R_TOTAL_SEED_PROCESSED, :P3_R_OIL_REC, :P3_R_CAKE_KHAL, ''WASTE_PCT'') || ''%''  AS "Waste / Loss"',
'',
'',
'-- from dual',
'',
'',
'',
'SELECT',
'    ''Wash Oil''  AS LABEL,',
'    PKG_OIL_MILL_CALCULATOR.CALCULATE_OIL_RECOVERY(:P3_R_TOTAL_SEED_PROCESSED, :P3_R_OIL_REC, :P3_R_CAKE_KHAL, ''OIL_KG'') AS KG_VALUE,',
'    PKG_OIL_MILL_CALCULATOR.CALCULATE_OIL_RECOVERY(:P3_R_TOTAL_SEED_PROCESSED, :P3_R_OIL_REC, :P3_R_CAKE_KHAL, ''OIL_PCT'') AS PCT_VALUE',
'FROM DUAL ',
'',
'UNION ALL',
'',
'SELECT',
'    ''Oil Cake (Khal)''  AS LABEL,',
'    PKG_OIL_MILL_CALCULATOR.CALCULATE_OIL_RECOVERY(:P3_R_TOTAL_SEED_PROCESSED, :P3_R_OIL_REC, :P3_R_CAKE_KHAL, ''CAKE_KG'') AS KG_VALUE,',
'    PKG_OIL_MILL_CALCULATOR.CALCULATE_OIL_RECOVERY(:P3_R_TOTAL_SEED_PROCESSED, :P3_R_OIL_REC, :P3_R_CAKE_KHAL, ''CAKE_PCT'') AS PCT_VALUE',
'FROM DUAL ',
'',
'UNION ALL ',
'',
'SELECT',
'    ''Waste / Loss''  AS LABEL,',
'    PKG_OIL_MILL_CALCULATOR.CALCULATE_OIL_RECOVERY(:P3_R_TOTAL_SEED_PROCESSED, :P3_R_OIL_REC, :P3_R_CAKE_KHAL, ''WASTE_KG'') AS KG_VALUE,',
'    PKG_OIL_MILL_CALCULATOR.CALCULATE_OIL_RECOVERY(:P3_R_TOTAL_SEED_PROCESSED, :P3_R_OIL_REC, :P3_R_CAKE_KHAL, ''WASTE_PCT'') AS PCT_VALUE',
'FROM DUAL '))
,p_ajax_enabled=>'Y'
